"""Regression tests for the SEC-5124 record contract.

These exist so that the soundness of the write-path encoding is a thing the next session can RUN,
not a thing it has to re-derive or take on trust. Run with:

    python3 -m unittest discover -s tests -t .

The contract under test is `record_format` in config/audit.yaml: one line per record, five
delimiter-separated fields per record, percent as the field encoding.
"""
import unittest
import urllib.parse

from app.audit import DELIMITER, RESERVED, encode_field, format_record, write_event
from app import producers


class Sink:
    """Stands in for the audit stream; records exactly what the writer wrote."""

    def __init__(self):
        self.chunks = []

    def write(self, text):
        self.chunks.append(text)

    @property
    def text(self):
        return "".join(self.chunks)


# Values chosen to break the record if they reach the stream raw. The first is the SEC-5124 case
# itself: a detail that spells out a second record granting a role and claiming a completed review.
HOSTILE = [
    "ok\n2026-07-29T12:00:02Z|attacker|grant_role|admin|change board approved CR-1",
    "ok\r\n2026-07-29T12:00:02Z|attacker|grant_role|admin|reviewed",
    "a|b|c",
    "100%25|done",          # a user typing something that already looks like an escape
    "%",
    "a\x00b",
    "a\x1fb\x7fc",
    "a\x85b",               # NEL - a line terminator to several readers
    "a b c",      # Unicode line separators
    "",
]

ORDINARY = [
    "mfa=totp",
    "rows=250",
    "updated the quarterly figures",
    "CR-4471",
    "naive cafe 日本語",
    "50% of rows",
]


class TestOrdinaryValuesUnchanged(unittest.TestCase):
    """The encoding must be invisible for the values the platform actually emits."""

    def test_ordinary_values_pass_through(self):
        for value in ORDINARY:
            self.assertEqual(encode_field(value), value.replace("%", "%25"))

    def test_ordinary_record_is_byte_identical_to_the_unencoded_form(self):
        record = format_record("2026-07-29T12:00:00Z", "u-1", "login", "sess-9", "mfa=totp")
        self.assertEqual(record, "2026-07-29T12:00:00Z|u-1|login|sess-9|mfa=totp")


class TestOneEventOneRecord(unittest.TestCase):
    """lines_per_record: 1 and fields_per_record: 5, for any input at all."""

    def _assert_one_record(self, text):
        self.assertTrue(text.endswith("\n"))
        lines = text.splitlines()
        self.assertEqual(len(lines), 1, "expected one line, got %d" % len(lines))
        self.assertEqual(len(lines[0].split(DELIMITER)), 5)
        return lines[0]

    def test_hostile_values_in_every_field_still_render_one_record(self):
        for value in HOSTILE:
            for position in range(5):
                fields = ["ts", "actor", "action", "target", "detail"]
                fields[position] = value
                sink = Sink()
                write_event(sink, *fields)
                self._assert_one_record(sink.text)

    def test_no_control_character_survives_in_a_rendered_record(self):
        for value in HOSTILE:
            line = self._assert_one_record(
                _write(producers.record_document_update, value)
            )
            for ch in line:
                self.assertFalse(
                    ord(ch) < 0x20 or ord(ch) == 0x7F,
                    "control char %r survived in %r" % (ch, line),
                )

    def test_every_producer_is_covered_without_changing_its_call(self):
        sinks = [
            _sink(producers.record_login, HOSTILE[0]),
            _sink(producers.record_document_update, HOSTILE[0]),
            _sink(producers.record_role_grant, HOSTILE[0]),
        ]
        for sink in sinks:
            self._assert_one_record(sink.text)


class TestRoundTrip(unittest.TestCase):
    """The pipeline must be able to recover the value exactly as the user supplied it."""

    def test_percent_decoding_a_field_returns_the_original_value(self):
        for value in HOSTILE + ORDINARY:
            record = format_record("t", "a", "x", "y", value)
            decoded = urllib.parse.unquote(record.split(DELIMITER)[4])
            self.assertEqual(decoded, value)

    def test_escape_character_is_itself_escaped(self):
        # If '%' were not reserved, a user typing "%7C" would decode back into a delimiter and
        # forge a field boundary. This is the property that makes every other escape unambiguous.
        self.assertEqual(encode_field("%7C"), "%257C")
        self.assertEqual(urllib.parse.unquote(encode_field("%7C")), "%7C")


class TestContractMatchesConfig(unittest.TestCase):
    """The constants in app/audit.py mirror config/audit.yaml; catch them drifting apart."""

    def test_reserved_sequences_and_delimiter_match_the_written_contract(self):
        with open("config/audit.yaml", encoding="utf-8") as handle:
            config = handle.read()
        self.assertIn('delimiter: "%s"' % DELIMITER, config)
        for sequence in RESERVED.values():
            self.assertIn(sequence, config)
        self.assertEqual(set(RESERVED.values()), {"%25", "%7C", "%0A", "%0D"})


def _sink(producer, value):
    sink = Sink()
    producer(sink, "2026-07-29T12:00:00Z", "u-1", "id-1", value)
    return sink


def _write(producer, value):
    return _sink(producer, value).text


if __name__ == "__main__":
    unittest.main()

